recipes.code:
{
  "inputs": [
    {
      "id": "clipform-api-key",
      "type": "promptString",
      "description": "API key that scopes tool calls to your workspace (create one in the dashboard under Settings, API keys). Not needed to list tools, only to call them.",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@clipform/mcp-server@2.2.2"
      ],
      "env": {
        "CLIPFORM_API_KEY": "${input:clipform-api-key}",
        "API_URL": "https://api.clipform.io"
      }
    }
  }
}
